const veiculos = $input.all();
const resultados = [];

function deizarAmigavel(texto) {
    if (!texto) return '';
    return texto
        .toString()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/\./g, '')
        .replace(/[^a-zA-Z0-9\s-]/g, '')
        .trim()
        .split(/[\s-]+/)
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join('-');
}

for (const item of veiculos) {
    const carro = item.json;
    const id = parseInt(carro.ID);

    const precoOriginal = parseFloat(carro.PRICE || 0);
    let precoPromo = parseFloat(carro.PROMOTION_PRICE || 0);
    const precoFinal = (precoPromo > 0 && precoPromo < precoOriginal) ? precoPromo : precoOriginal;

    if (!(precoPromo > 0 && precoPromo < precoOriginal)) {
        precoPromo = 0;
    }

    const marcaSlug = deizarAmigavel(carro.MAKE);
    const modeloBaseSlug = deizarAmigavel(carro.BASE_MODEL);
    const baseModelRegex = new RegExp(`^${carro.BASE_MODEL}`, 'i');
    const versaoLimpa = (carro.MODEL || '').replace(baseModelRegex, '').trim();
    const versaoSlug = deizarAmigavel(versaoLimpa);
    const modeloCompletoSlug = deizarAmigavel(carro.MODEL);
    const cidadeSlug = deizarAmigavel(carro.LOCATION_CITY);
    const estadoSlug = deizarAmigavel(carro.LOCATION_STATE);

    const linkSite = `https://motorsstoreoficial.com.br/carros/${marcaSlug}/${modeloBaseSlug}/${versaoSlug}/${marcaSlug}-${modeloCompletoSlug}-${carro.YEAR}-${cidadeSlug}-${estadoSlug}-${id}.html`;

    let urlImagem = "";
    if (carro.IMAGES_LARGE?.IMAGE_URL_LARGE) {
        urlImagem = Array.isArray(carro.IMAGES_LARGE.IMAGE_URL_LARGE) ? carro.IMAGES_LARGE.IMAGE_URL_LARGE[0] : carro.IMAGES_LARGE.IMAGE_URL_LARGE;
    } else if (carro.IMAGES?.IMAGE_URL) {
        urlImagem = Array.isArray(carro.IMAGES.IMAGE_URL) ? carro.IMAGES.IMAGE_URL[0] : carro.IMAGES.IMAGE_URL;
    }

    const modeloLower = (carro.MODEL || '').toLowerCase();
    const makeLower = (carro.MAKE || '').toLowerCase();
    const categoryLower = (carro.CATEGORY || '').toLowerCase();
    const bodyTypeLower = (carro.BODY_TYPE || '').toLowerCase();

    let tipo = "Hatch";
    if (categoryLower === "motocicleta" || categoryLower === "moto" || modeloLower.match(/(cb|twister|harley|davidson|moto)/)) {
        tipo = "Motocicleta";
    } else if (bodyTypeLower === "suv" || modeloLower.match(/(renegade|ecosport|tiguan|taos|x1|x4|duster|tracker|toro)/)) {
        tipo = "SUV";
    } else if (bodyTypeLower === "sedan" || modeloLower.match(/(prisma|cruze|classic|c-180|c 180|seda)/)) {
        tipo = "Sedan";
    } else if (bodyTypeLower === "picape" || modeloLower.match(/(amarok|saveiro|hilux|s10|ranger)/)) {
        tipo = "Picape";
    } else if (bodyTypeLower === "hatch" || modeloLower.match(/(gol|c3|palio|fiesta|march|mobi|polo|argo|clio|fit|fox)/)) {
        tipo = "Hatch";
    }

    let perfilUso = "Uso Diário";
    if (tipo === "Motocicleta") {
        perfilUso = "Agilidade / Economia";
    } else if (makeLower.match(/(porsche|bmw|mercedes|audi|land-rover)/) || modeloLower.match(/(m sport|gts|turbo|r-line|amg)/)) {
        perfilUso = "Performance / Premium";
    } else if (tipo === "SUV" || tipo === "Sedan" || modeloLower.match(/(weekend|allspace|family|familia|fit)/)) {
        perfilUso = "Família / Conforto";
    } else if (tipo === "Picape" || (carro.FUEL || '').toLowerCase() === "diesel") {
        perfilUso = "Trabalho / Robustez";
    } else if (parseFloat(carro.MOTOR || 0) <= 1.0 || modeloLower.match(/(gol|mobi|march|clio|argo|uno|fox)/)) {
        perfilUso = "Econômico / Diário";
    }

    resultados.push({
        json: {
            id: id,
            marca: carro.MAKE || "N/D",
            modelo: carro.MODEL || "N/D",
            versao: versaoLimpa || "Série",
            ano: parseInt(carro.YEAR || 0),
            ano_fabricacao: parseInt(carro.FABRIC_YEAR || 0),
            preco: precoFinal,
            preco_original: precoOriginal,
            preco_promocional: precoPromo,
            quilometragem: parseInt(carro.MILEAGE || 0),
            cambio: carro.GEAR || "N/D",
            combustivel: carro.FUEL || "N/D",
            cor: carro.COLOR || "N/D",
            tipo: tipo,
            perfil_uso: perfilUso,
            url_imagem: urlImagem,
            link_conversao: linkSite,
            pericia: carro.PERICIA || "Em análise",
            descricao: carro.DESCRIPTION || "Sem descrição informada",
            whatsapp_images: Array.isArray(carro.IMAGES?.IMAGE_URL) ? carro.IMAGES.IMAGE_URL : [carro.IMAGES?.IMAGE_URL || ''],
            web_full_images: Array.isArray(carro.IMAGES_LARGE?.IMAGE_URL_LARGE) ? carro.IMAGES_LARGE.IMAGE_URL_LARGE : [carro.IMAGES_LARGE?.IMAGE_URL_LARGE || ''],
            // Documentação do veículo e referência de mercado: o feed sempre
            // mandou, e até 2026-08-17 o mapeamento descartava. Alimentam o
            // fechamento de venda da A19 (chassi e placa eram digitados à mão).
            // USO INTERNO: não entram no mapper público do site.
            placa: (carro.PLATE || '').toString().trim().toUpperCase() || null,
            chassi: (carro.CHASSI || '').toString().trim().toUpperCase() || null,
            motor: (carro.MOTOR || '').toString().trim() || null,
            valor_fipe: parseFloat(carro.VALOR_FIPE || 0) || null,
            codigo_fipe: (carro.FIPE || '').toString().trim() || null
        }
    });
}

return resultados;
